// Timing instrumentation
struct TimingStats {
    std::chrono::high_resolution_clock::duration get_points_from_grid{0};
    std::chrono::high_resolution_clock::duration get_conv_from_grid{0};
    std::chrono::high_resolution_clock::duration convex_hull{0};
    std::chrono::high_resolution_clock::duration find_F{0};
    std::chrono::high_resolution_clock::duration find_tangent_idx{0};
    std::chrono::high_resolution_clock::duration intersect_ray_with_rect{0};
    std::chrono::high_resolution_clock::duration polygon_construct{0};
    std::chrono::high_resolution_clock::duration cgal_intersection{0};
    std::chrono::high_resolution_clock::duration other{0};

    long long get_points_from_grid_calls = 0;
    long long get_conv_from_grid_calls = 0;
    long long convex_hull_calls = 0;
    long long find_F_calls = 0;
    long long find_tangent_calls = 0;
    long long intersect_calls = 0;
    long long polygon_construct_calls = 0;
    long long cgal_intersection_calls = 0;

    void print_report() const {
        auto total_ms = std::chrono::duration<double, std::milli>(
            get_points_from_grid + get_conv_from_grid + convex_hull +
            find_F + find_tangent_idx + intersect_ray_with_rect +
            polygon_construct + cgal_intersection + other
        ).count();

        std::cout << "\n=== TIMING REPORT ===\n";
        std::cout << std::fixed << std::setprecision(2);
        std::cout << "Operation                    |    Time (ms) |       % |  Calls |   ms/call\n";
        std::cout << "-----------------------------|-------------|--------|--------|----------\n";

        auto print_row = [&](const char* name, auto duration, long long calls) {
            auto ms = std::chrono::duration<double, std::milli>(duration).count();
            double pct = total_ms > 0 ? (ms / total_ms) * 100 : 0;
            double ms_per_call = calls > 0 ? ms / calls : 0;
            std::cout << std::setw(28) << std::left << name << " | "
                      << std::setw(10) << std::right << ms << " | "
                      << std::setw(6) << std::fixed << std::setprecision(1) << pct << "% | "
                      << std::setw(6) << calls << " | "
                      << std::setprecision(4) << ms_per_call << "\n";
        };

        print_row("get_points_from_grid", get_points_from_grid, get_points_from_grid_calls);
        print_row("get_conv_from_grid", get_conv_from_grid, get_conv_from_grid_calls);
        print_row("  convex_hull", convex_hull, convex_hull_calls);
        print_row("find_F", find_F, find_F_calls);
        print_row("  find_tangent_idx", find_tangent_idx, find_tangent_calls);
        print_row("  intersect_ray_with_rect", intersect_ray_with_rect, intersect_calls);
        print_row("  polygon_construct", polygon_construct, polygon_construct_calls);
        print_row("CGAL::intersection", cgal_intersection, cgal_intersection_calls);
        print_row("other", other, 1);
        std::cout << "-----------------------------|-------------|--------|--------|----------\n";
        std::cout << std::setw(28) << std::left << "TOTAL" << " | "
                  << std::setw(10) << std::fixed << std::setprecision(2) << total_ms << " |\n";
    }
};

TimingStats g_timing;

#define TIME_SCOPE(stats_field, calls_field) \
    auto _timing_start = std::chrono::high_resolution_clock::now(); \
    ++g_timing.calls_field;

#define TIME_END(stats_field) \
    g_timing.stats_field += std::chrono::high_resolution_clock::now() - _timing_start;

