                if (showG && viewer) {
                    viewer->addPolygon(Gi_poly, c);
                }
                if (showS && viewer) {
                    viewer->addPolygon(S_poly, c);
                }
                shown_debug = true;
            }

            std::vector<Point> inter_result;
            if (use_convex_intersection) {
                inter_result = convex_polygon_intersection(F, Gi);
                if (inter_result.empty()) {
                    dead[i] = true;
                    dead_cnt++;
                    continue;
                }
                new_S[i].push_back(Polygon_with_holes(Polygon(inter_result.begin(), inter_result.end())));
                buffer[1] = inter_result[0];
            } else {
                // Validate polygons before intersection
                bool valid_polygons = true;
                if (F.size() < 3 || Gi.size() < 3) {
                    valid_polygons = false;
                }
                if (valid_polygons) {
                    double F_area = std::abs(CGAL::to_double(CGAL::area(F[0], F[1], F[2])));
                    double Gi_area = std::abs(CGAL::to_double(CGAL::area(Gi[0], Gi[1], Gi[2])));
