};

// Simple visualization widget
class PolygonViewer : public QWidget {
public:
    Polygon F, Gi;
    double scale = 1.0;
    double offsetX = 0, offsetY = 0;

    PolygonViewer(QWidget* parent = nullptr) : QWidget(parent) {
        setMinimumSize(800, 600);
        setWindowTitle("CGAL Intersection Failure Test");
    }

    void setPolygons(const Polygon& f, const Polygon& g) {
        F = f;
        Gi = g;
        computeTransform();
        update();
    }

    void computeTransform() {
        // Find bounding box of both polygons
        double minX = 1e100, maxX = -1e100;
        double minY = 1e100, maxY = -1e100;

        auto updateBounds = [&](const Polygon& poly) {
            for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
                double x = CGAL::to_double(it->x());
                double y = CGAL::to_double(it->y());
                minX = std::min(minX, x);
                maxX = std::max(maxX, x);
                minY = std::min(minY, y);
                maxY = std::max(maxY, y);
            }
        };

        updateBounds(F);
        updateBounds(Gi);

        // Add padding
        double padX = (maxX - minX) * 0.1;
        double padY = (maxY - minY) * 0.1;
        minX -= padX; maxX += padX;
        minY -= padY; maxY += padY;

        // Compute scale to fit in window
        double scaleX = (width() - 40) / (maxX - minX);
        double scaleY = (height() - 40) / (maxY - minY);
        scale = std::min(scaleX, scaleY);

        offsetX = (width() - (maxX - minX) * scale) / 2 - minX * scale;
        offsetY = (height() - (maxY - minY) * scale) / 2 - minY * scale;
    }

    void resizeEvent(QResizeEvent*) override {
        computeTransform();
    }

    void paintEvent(QPaintEvent*) override {
        QPainter p(this);
        p.setRenderHint(QPainter::Antialiasing);

        // Background
        p.fillRect(rect(), Qt::white);

        // Transform helper
        auto transform = [&](const Point& pt) -> QPointF {
            return QPointF(
                CGAL::to_double(pt.x()) * scale + offsetX,
                height() - (CGAL::to_double(pt.y()) * scale + offsetY)
            );
        };

        // Draw F polygon (blue, filled)
        p.setPen(Qt::blue);
        p.setBrush(QBrush(QColor(100, 149, 237, 80)));
        QPolygonF polyF;
        for (auto it = F.vertices_begin(); it != F.vertices_end(); ++it) {
            polyF.append(transform(*it));
        }
        p.drawPolygon(polyF);

        // Draw Gi polygon (red, filled)
        p.setPen(Qt::red);
        p.setBrush(QBrush(QColor(255, 99, 71, 80)));
        QPolygonF polyGi;
        for (auto it = Gi.vertices_begin(); it != Gi.vertices_end(); ++it) {
            polyGi.append(transform(*it));
        }
        p.drawPolygon(polyGi);

        // Draw vertex points for F
        p.setBrush(Qt::blue);
        for (auto it = F.vertices_begin(); it != F.vertices_end(); ++it) {
            p.drawEllipse(transform(*it), 4, 4);
        }

        // Draw vertex points for Gi
        p.setBrush(Qt::red);
        for (auto it = Gi.vertices_begin(); it != Gi.vertices_end(); ++it) {
            p.drawEllipse(transform(*it), 3, 3);
        }

        // Draw labels
        p.setPen(Qt::blue);
        p.drawText(10, 20, "F (blue): Large square [-10000, 10000]^2");
        p.setPen(Qt::red);
        p.drawText(10, 40, "Gi (red): Convex polygon, 22 vertices");
        p.setPen(Qt::black);
        p.drawText(10, 60, "Kernel: " + QString(USE_EXACT_KERNEL ? "Exact (Epeck)" : "Simple_cartesian<double>"));
        p.drawText(10, 80, "Polygon F is_simple: " + QString(F.is_simple() ? "true" : "false"));
        p.drawText(10, 100, "Polygon Gi is_simple: " + QString(Gi.is_simple() ? "true" : "false"));
    }
};

int main(int argc, char* argv[]) {
    QApplication app(argc, argv);

    std::cout << "=== CGAL::intersection Failure Test ===" << std::endl;
    std::cout << "Kernel: " << (USE_EXACT_KERNEL ? "Exact_predicates_exact_constructions_kernel" : "Simple_cartesian<double>") << std::endl;
    std::cout << std::endl;

    // Create polygons
    Polygon F(F_points.begin(), F_points.end());
    Polygon Gi(Gi_points.begin(), Gi_points.end());

    std::cout << "F: " << F.size() << " vertices, is_simple=" << F.is_simple() << std::endl;
    std::cout << "Gi: " << Gi.size() << " vertices, is_simple=" << Gi.is_simple() << std::endl;
    std::cout << std::endl;

    // Create viewer
    PolygonViewer viewer;
    viewer.setPolygons(F, Gi);
    viewer.show();

    std::cout << "Calling CGAL::intersection(F, Gi)..." << std::endl;

    // Try intersection
    std::vector<Polygon_with_holes> result;
    try {
        CGAL::intersection(F, Gi, std::back_inserter(result));
        std::cout << "SUCCESS! Intersection produced " << result.size() << " polygon(s)" << std::endl;
    } catch (const std::exception& e) {
        std::cout << "EXCEPTION: " << e.what() << std::endl;
    } catch (...) {
        std::cout << "UNKNOWN EXCEPTION (likely SIGSEGV)" << std::endl;
    }

    std::cout << std::endl;
    std::cout << "Close the window to exit, or press Ctrl+C in terminal." << std::endl;

    return app.exec();
}

