// Reproduce simplify's CGAL intersection with same algorithm
// This should trigger the same assertion violation as simplify with Simple_cartesian

#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <sstream>
#include <cmath>

#include "kernel.h"

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;

// Check if point p is in the epsilon tube around the segment (a, b)
bool in_epsilon_tube(const Point& p, const Point& a, const Point& b, double eps) {
    double x1 = CGAL::to_double(a.x()), y1 = CGAL::to_double(a.y());
    double x2 = CGAL::to_double(b.x()), y2 = CGAL::to_double(b.y());
    double xp = CGAL::to_double(p.x()), yp = CGAL::to_double(p.y());

    double dx = x2 - x1, dy = y2 - y1;
    double len_sq = dx*dx + dy*dy;
    if (len_sq == 0) return sqrt((xp-x1)*(xp-x1) + (yp-y1)*(yp-y1)) <= eps;

    double t = std::max(0.0, std::min(1.0, ((xp-x1)*dx + (yp-y1)*dy) / len_sq));
    double projx = x1 + t*dx, projy = y1 + t*dy;

    return sqrt((xp-projx)*(xp-projx) + (yp-projy)*(yp-projy)) <= eps;
}

// Get convex hull from grid (simplified version)
std::vector<Point> get_conv_from_grid(const Point& pi) {
    std::vector<Point> result;
    double xi = CGAL::to_double(pi.x()), yi = CGAL::to_double(pi.y());

    // Generate 16 points around pi
    for (int dx = -1; dx <= 1; dx += 1) {
        for (int dy = -1; dy <= 1; dy += 1) {
            if (dx == 0 && dy == 0) continue;
            result.emplace_back(xi + dx * DELTA, yi + dy * DELTA);
        }
    }

    // Find convex hull (Andrew's monotone chain)
    std::sort(result.begin(), result.end(), [](const Point& a, const Point& b) {
        double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
        double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
        return ax < bx || (ax == bx && ay < by);
    });

    std::vector<Point> hull;
    for (const auto& p : result) {
        while (hull.size() >= 2 && 
               CGAL::orientation(hull[hull.size()-2], hull[hull.size()-1], p) == CGAL::COLLINEAR &&
               CGAL::collinear_are_ordered_along_line(hull[hull.size()-2], hull[hull.size()-1], p)) {
            hull.pop_back();
        }
        while (hull.size() >= 2 &&
               CGAL::orientation(hull[hull.size()-2], hull[hull.size()-1], p) != CGAL::RIGHT_TURN) {
            hull.pop_back();
        }
        hull.push_back(p);
    }

    // Lower hull
    std::vector<Point> lower = hull;
    for (int i = int(result.size()) - 2; i >= 0; --i) {
        const auto& p = result[i];
        while (lower.size() >= 2 &&
               CGAL::orientation(lower[lower.size()-2], lower[lower.size()-1], p) == CGAL::COLLINEAR &&
               CGAL::collinear_are_ordered_along_line(lower[lower.size()-2], lower[lower.size()-1], p)) {
            lower.pop_back();
        }
        while (lower.size() >= 2 &&
               CGAL::orientation(lower[lower.size()-2], lower[lower.size()-1], p) != CGAL::RIGHT_TURN) {
            lower.pop_back();
        }
        lower.push_back(p);
    }

    // Remove duplicates
    for (auto& p : lower) {
        bool found = false;
        for (auto& h : hull) {
            if (CGAL::exact(h) == CGAL::exact(p)) { found = true; break; }
        }
        if (!found) hull.push_back(p);
    }

    return hull;
}

// Find F polygon (epsilon tube around trajectory)
std::vector<Point> find_F(const Point& p0, const std::vector<Point>& trajectory, double eps) {
    std::vector<Point> result;
    result.push_back(p0);

    int n = trajectory.size();
    for (int i = 0; i < n; ++i) {
        Point prev = (i == 0) ? p0 : trajectory[i-1];
        Point curr = trajectory[i];
        Point next = (i == n-1) ? trajectory[i] : trajectory[i+1];

        double dx_next = CGAL::to_double(next.x()) - CGAL::to_double(curr.x());
        double dy_next = CGAL::to_double(next.y()) - CGAL::to_double(curr.y());
        double len_next = sqrt(dx_next*dx_next + dy_next*dy_next);
        if (len_next > 0) {
            dx_next /= len_next; dy_next /= len_next;
        }
        double nx = -dy_next * eps, ny = dx_next * eps;

        result.emplace_back(CGAL::to_double(curr.x()) + nx, CGAL::to_double(curr.y()) + ny);
    }

    for (int i = n-1; i >= 0; --i) {
        Point prev = (i == 0) ? p0 : trajectory[i-1];
        Point curr = trajectory[i];
        Point next = (i == n-1) ? trajectory[i] : trajectory[i+1];

        double dx_next = CGAL::to_double(next.x()) - CGAL::to_double(curr.x());
        double dy_next = CGAL::to_double(next.y()) - CGAL::to_double(curr.y());
        double len_next = sqrt(dx_next*dx_next + dy_next*dy_next);
        if (len_next > 0) {
            dx_next /= len_next; dy_next /= len_next;
        }
        double nx = dy_next * eps, ny = -dx_next * eps;

        result.emplace_back(CGAL::to_double(curr.x()) + nx, CGAL::to_double(curr.y()) + ny);
    }

    return result;
}

