// Simple visualization widget
class PolygonViewer : public QWidget {
public:
    Polygon F, Gi;
    double scale = 1.0;
    double offsetX = 0, offsetY = 0;

    PolygonViewer(QWidget* parent = nullptr) : QWidget(parent) {
        setMinimumSize(800, 600);
#ifdef USE_EXACT_KERNEL
        setWindowTitle("CGAL Intersection - EXACT Kernel (should work)");
#else
        setWindowTitle("CGAL Intersection - Simple_cartesian (should FAIL)");
#endif
    }

    void setPolygons(const Polygon& f, const Polygon& g) {
        F = f;
        Gi = g;
        computeTransform();
        update();
    }

    void computeTransform() {
        double minX = 1e100, maxX = -1e100;
        double minY = 1e100, maxY = -1e100;

        auto updateBounds = [&](const Polygon& poly) {
            for (auto it = poly.vertices_begin(); it != poly.vertices_end(); ++it) {
                double x = CGAL::to_double(it->x());
                double y = CGAL::to_double(it->y());
                minX = std::min(minX, x);
                maxX = std::max(maxX, x);
                minY = std::min(minY, y);
                maxY = std::max(maxY, y);
            }
        };

        updateBounds(F);
        updateBounds(Gi);

        double padX = (maxX - minX) * 0.1;
        double padY = (maxY - minY) * 0.1;
        minX -= padX; maxX += padX;
        minY -= padY; maxY += padY;

        double scaleX = (width() - 40) / (maxX - minX);
        double scaleY = (height() - 40) / (maxY - minY);
        scale = std::min(scaleX, scaleY);

        offsetX = (width() - (maxX - minX) * scale) / 2 - minX * scale;
        offsetY = (height() - (maxY - minY) * scale) / 2 - minY * scale;
    }

    void resizeEvent(QResizeEvent*) override {
        computeTransform();
    }

    void paintEvent(QPaintEvent*) override {
        QPainter p(this);
        p.setRenderHint(QPainter::Antialiasing);

        p.fillRect(rect(), Qt::white);

        auto transform = [&](const Point& pt) -> QPointF {
            return QPointF(
                CGAL::to_double(pt.x()) * scale + offsetX,
                height() - (CGAL::to_double(pt.y()) * scale + offsetY)
            );
        };

        // Draw F polygon (blue)
        p.setPen(Qt::blue);
        p.setBrush(QBrush(QColor(100, 149, 237, 80)));
        QPolygonF polyF;
        for (auto it = F.vertices_begin(); it != F.vertices_end(); ++it) {
            polyF.append(transform(*it));
        }
        p.drawPolygon(polyF);

        // Draw Gi polygon (red)
        p.setPen(Qt::red);
        p.setBrush(QBrush(QColor(255, 99, 71, 80)));
        QPolygonF polyGi;
        for (auto it = Gi.vertices_begin(); it != Gi.vertices_end(); ++it) {
            polyGi.append(transform(*it));
        }
        p.drawPolygon(polyGi);

        // Labels
        p.setPen(Qt::blue);
        p.drawText(10, 20, "F (blue): Large square [-10000, 10000]^2");
        p.setPen(Qt::red);
        p.drawText(10, 40, "Gi (red): Convex polygon, 22 vertices");
        p.setPen(Qt::black);
#ifdef USE_EXACT_KERNEL
        p.drawText(10, 60, "Kernel: EXACT - intersection should WORK");
#else
        p.drawText(10, 60, "Kernel: Simple_cartesian - intersection should FAIL!");
#endif
        p.drawText(10, 80, "F is_simple: " + QString(F.is_simple() ? "true" : "false"));
        p.drawText(10, 100, "Gi is_simple: " + QString(Gi.is_simple() ? "true" : "false"));
    }
};

