        const Point& b = S[(i + 1) % n];
        if (CGAL::orientation(a, b, p) != CGAL::LEFT_TURN) {
            return false;
        }
    }
    return true;
}

double cross(const Point& O, const Point& A, const Point& B) {
    return (CGAL::to_double(A.x()) - CGAL::to_double(O.x())) * (CGAL::to_double(B.y()) - CGAL::to_double(O.y())) -
           (CGAL::to_double(A.y()) - CGAL::to_double(O.y())) * (CGAL::to_double(B.x()) - CGAL::to_double(O.x()));
}

std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
