#ifdef USE_EXACT_KERNEL
        p.drawText(10, 60, "Kernel: EXACT (Epeck) - intersection works!");
#else
        p.drawText(10, 60, "Kernel: Simple_cartesian<double> - intersection works!");
#endif
        p.drawText(10, 80, "Polygon F is_simple: " + QString(F.is_simple() ? "true" : "false"));
        p.drawText(10, 100, "Polygon Gi is_simple: " + QString(Gi.is_simple() ? "true" : "false"));
    }
};

