// Compare CGAL vs convex intersection on same input
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <algorithm>
#include <cmath>

#include "kernel.h"

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

// From simplify.cpp - convex polygon intersection
std::vector<Point> convex_polygon_intersection(const std::vector<Point>& P_input,
                                                 const std::vector<Point>& Q_input) {
    if (P_input.empty() || Q_input.empty()) return {};
    std::vector<Point> P = P_input;
    std::vector<Point> Q = Q_input;
    std::sort(P.begin(), P.end(), [](const Point& a, const Point& b) {
        double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
        double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
        return ax < bx || (ax == bx && ay < by);
    });
    std::sort(Q.begin(), Q.end(), [](const Point& a, const Point& b) {
        double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
        double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
        return ax < bx || (ax == bx && ay < by);
    });
    P.erase(std::unique(P.begin(), P.end(), [](const Point& a, const Point& b) {
        return CGAL::to_double(a.x()) == CGAL::to_double(b.x()) &&
               CGAL::to_double(a.y()) == CGAL::to_double(b.y());
    }), P.end());
    Q.erase(std::unique(Q.begin(), Q.end(), [](const Point& a, const Point& b) {
        return CGAL::to_double(a.x()) == CGAL::to_double(b.x()) &&
               CGAL::to_double(a.y()) == CGAL::to_double(b.y());
    }), Q.end());

    int n = P.size(), m = Q.size();
    if (n < 3 || m < 3) return {};
    std::vector<Point> result;
    int i = 0, j = 0;
    Point prevP = P[n-1], prevQ = Q[m-1];
    for (int k = 0; k < n + m; k++) {
        result.push_back((i < n) ? P[i] : P[i % n]);
        if (k % 2 == 0) {
            if (CGAL::orientation(prevQ, Q[j % m], P[i % n]) >= 0) {
                prevP = P[i % n];
                i++;
            } else {
                prevQ = Q[j % m];
                j++;
            }
        } else {
            if (CGAL::orientation(prevP, P[i % n], Q[j % m]) <= 0) {
                prevQ = Q[j % m];
                j++;
            } else {
                prevP = P[i % n];
                i++;
            }
        }
    }
    return result;
}

int main() {
    std::cout << "=== Comparing CGAL vs Convex intersection ===" << std::endl;

    // Load first few F, Gi from failed_polygons.txt
    std::vector<Point> F = {
        {-10000, -10000},
        {10000, -10000},
        {10000, 10000},
        {-10000, 10000}
    };

    std::vector<Point> Gi = {
        {-1034.88, 2618.3},
        {-992.454, 2533.44},
        {-950.027, 2491.02},
        {-907.601, 2448.59},
