// Visualize why get_conv_from_grid produces non-convex polygons
// This reproduces the issue from failed_polygons.txt

#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <cmath>
#include <QApplication>
#include <QPainter>
#include <QWidget>

#include "kernel.h"

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;

double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }

// Original get_conv_from_grid from simplify.cpp
std::vector<Point> get_conv_from_grid_original(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    // TODO: improve this implementation
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0) // to avoid duplicates
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(),
                        std::back_inserter(conv));
    return conv;
}

// Fixed version that ensures proper ordering
std::vector<Point> get_conv_from_grid_fixed(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_max; y >= y_min; y--) {  // Go in reverse order for right side
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0)
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(),
                        std::back_inserter(conv));
    return conv;
}

bool is_convex(const std::vector<Point>& pts) {
    int n = pts.size();
    if (n < 3) return true;
    for (int i = 0; i < n; i++) {
        const Point& a = pts[i];
        const Point& b = pts[(i + 1) % n];
        const Point& c = pts[(i + 2) % n];
        if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
            return false;
        }
    }
    return true;
}

bool is_counterclockwise(const std::vector<Point>& pts) {
    double sum = 0;
    for (int i = 0; i < (int)pts.size(); i++) {
        const Point& a = pts[i];
        const Point& b = pts[(i + 1) % pts.size()];
        sum += (CGAL::to_double(b.x()) - CGAL::to_double(a.x())) *
               (CGAL::to_double(b.y()) + CGAL::to_double(a.y()));
    }
    return sum > 0;
}

class GiViewer : public QWidget {
public:
    Point p0;
    std::vector<Point> Gi_original;
    std::vector<Point> Gi_fixed;
    std::vector<Point> boundaries;
    double scale = 1.0;
    double offsetX = 0, offsetY = 0;
    bool show_boundaries = true;
    bool show_fixed = false;

    GiViewer(QWidget* parent = nullptr) : QWidget(parent) {
        setMinimumSize(900, 500);
        setWindowTitle("Gi Polygon Visualization");
    }

    void setData(const Point& p, const std::vector<Point>& gi_orig,
                 const std::vector<Point>& gi_fixed, const std::vector<Point>& bounds) {
        p0 = p;
        Gi_original = gi_orig;
        Gi_fixed = gi_fixed;
        boundaries = bounds;
        computeTransform();
        update();
    }

    void computeTransform() {
        double minX = 1e100, maxX = -1e100;
        double minY = 1e100, maxY = -1e100;

        auto updateBounds = [&](const Point& pt) {
            double x = CGAL::to_double(pt.x());
            double y = CGAL::to_double(pt.y());
            minX = std::min(minX, x);
            maxX = std::max(maxX, x);
            minY = std::min(minY, y);
            maxY = std::max(maxY, y);
        };

        for (const auto& pt : Gi_original) updateBounds(pt);
        for (const auto& pt : boundaries) updateBounds(pt);

        // Add padding
        double padX = (maxX - minX) * 0.15;
        double padY = (maxY - minY) * 0.15;
        minX -= padX; maxX += padX;
        minY -= padY; maxY += padY;

        double scaleX = (width() / 2 - 20) / (maxX - minX);
        double scaleY = (height() - 40) / (maxY - minY);
        scale = std::min(scaleX, scaleY);

        offsetX = 20 - minX * scale;
        offsetY = height() / 2 - minY * scale;
    }

    void resizeEvent(QResizeEvent*) override { computeTransform(); }

    void paintEvent(QPaintEvent*) override {
        QPainter p(this);
        p.setRenderHint(QPainter::Antialiasing);
        p.fillRect(rect(), Qt::white);

        auto transform = [&](const Point& pt, int panel) -> QPointF {
            double x = CGAL::to_double(pt.x()) * scale + offsetX;
            double y = height() - (CGAL::to_double(pt.y()) * scale + offsetY);
            if (panel == 1) x += width() / 2;  // Right panel
            return QPointF(x, y);
        };

        // Draw center point p0
        QPointF p0_left = transform(p0, 0);
        QPointF p0_right = transform(p0, 1);
        p.setPen(Qt::black);
        p.setBrush(Qt::black);
        p.drawEllipse(p0_left, 5, 5);
        p.drawEllipse(p0_right, 5, 5);

        // Draw circle hint (radius = R)
        double r = R_val();
        p.setPen(QPen(Qt::gray, 1, Qt::DashLine));
        p.drawEllipse(p0_left, r * scale, r * scale);
        p.drawEllipse(p0_right, r * scale, r * scale);

        // LEFT PANEL: Original get_conv_from_grid
        p.setPen(Qt::blue);
        p.drawText(10, 20, "LEFT: Original (BUGGY)");

        // Draw boundaries
        if (show_boundaries && !boundaries.empty()) {
            p.setPen(QPen(Qt::lightGray, 1));
            p.setBrush(Qt::NoBrush);
            QPolygonF polyBound;
            for (const auto& pt : boundaries) {
                polyBound.append(transform(pt, 0));
            }
            p.drawPolyline(polyBound);
        }

        // Draw Gi_original
        Polygon polyOrig(Gi_original.begin(), Gi_original.end());
        p.setPen(Qt::blue);
        p.setBrush(QBrush(QColor(100, 149, 237, 80)));
        QPolygonF polyGiLeft;
        for (auto it = polyOrig.vertices_begin(); it != polyOrig.vertices_end(); ++it) {
            polyGiLeft.append(transform(*it, 0));
        }
        if (polyGiLeft.size() > 0) {
            polyGiLeft.append(polyGiLeft[0]); // Close polygon
            p.drawPolyline(polyGiLeft);
        }

        // Highlight non-convex vertices
        for (int i = 0; i < (int)Gi_original.size(); i++) {
            const Point& a = Gi_original[i];
            const Point& b = Gi_original[(i + 1) % Gi_original.size()];
            const Point& c = Gi_original[(i + 2) % Gi_original.size()];
            if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
                p.setBrush(Qt::red);
                p.drawEllipse(transform(b, 0), 6, 6);
            }
        }

        // Right panel label
        p.setPen(Qt::green);
        p.drawText(width() / 2 + 10, 20, "RIGHT: Fixed");

        // Draw Gi_fixed
        if (!Gi_fixed.empty()) {
            p.setPen(Qt::green);
            p.setBrush(QBrush(QColor(144, 238, 144, 80)));
            QPolygonF polyGiRight;
            for (const auto& pt : Gi_fixed) {
                polyGiRight.append(transform(pt, 1));
            }
            if (polyGiRight.size() > 0) {
                polyGiRight.append(polyGiRight[0]);
                p.drawPolyline(polyGiRight);
            }
        }

        // Info text
        p.setPen(Qt::black);
        p.drawText(10, height() - 60, "p0 = (" + QString::number(CGAL::to_double(p0.x()), 'f', 2) +
                   ", " + QString::number(CGAL::to_double(p0.y()), 'f', 2) + ")");
        p.drawText(10, height() - 40, "R = " + QString::number(r, 'f', 2) +
                   ", GRID = " + QString::number(GRID_val(), 'f', 2));
        p.drawText(10, height() - 20, "Original: " + QString::number(Gi_original.size()) +
                   " pts, convex=" + (is_convex(Gi_original) ? "YES" : "NO"));
        p.drawText(width() / 2 + 10, height() - 20, "Fixed: " + QString::number(Gi_fixed.size()) +
                   " pts, convex=" + (is_convex(Gi_fixed) ? "YES" : "NO"));
    }

    void mousePressEvent(QMouseEvent*) override {
        show_boundaries = !show_boundaries;
        show_fixed = !show_fixed;
        update();
    }
};

