// Comprehensive test to find why CGAL::intersection fails with Simple_cartesian
// This iterates through actual F/Gi pairs from simplify and tests them

#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <cmath>
#include <QApplication>
#include <QPainter>
#include <QWidget>

#include "kernel.h"

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;

double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0)
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> points;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        const int x_max = -x_min;
        for (int x = x_min; x <= x_max; x++) {
            points.emplace_back(px + x * GRID, py + y_actual);
        }
    }
    return points;
}

std::vector<Point> current_bbox() {
    return {{-10000, -10000}, {10000, -10000}, {10000, 10000}, {-10000, 10000}};
}

bool is_convex(const std::vector<Point>& pts) {
    int n = pts.size();
    if (n < 3) return true;
    for (int i = 0; i < n; i++) {
        const Point& a = pts[i];
        const Point& b = pts[(i + 1) % n];
        const Point& c = pts[(i + 2) % n];
        if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
            return false;
        }
    }
    return true;
}

// Check if polygon is simple (non-self-intersecting)
bool is_simple(const std::vector<Point>& pts) {
    Polygon poly(pts.begin(), pts.end());
    return poly.is_simple();
}

// Load trajectory from file
std::vector<Point> load_trajectory(const std::string& path) {
    std::ifstream fin(path);
    if (!fin) return {};
    int N;
    fin >> N;
    std::vector<Point> stream;
    for (int i = 0; i < N; i++) {
        double x, y;
        fin >> x >> y;
        stream.emplace_back(x, y);
    }
    return stream;
}

class GiViewer : public QWidget {
public:
    std::vector<Point> Gi;
    int non_convex_vertex = -1;
    double scale = 1.0;
    double offsetX = 0, offsetY = 0;

    GiViewer(QWidget* parent = nullptr) : QWidget(parent) {
        setMinimumSize(800, 600);
        setWindowTitle("Non-Convex Gi Visualization");
    }

    void setGi(const std::vector<Point>& gi, int bad_vertex = -1) {
        Gi = gi;
        non_convex_vertex = bad_vertex;
        computeTransform();
        update();
    }

    void computeTransform() {
        double minX = 1e100, maxX = -1e100;
        double minY = 1e100, maxY = -1e100;
        for (const auto& pt : Gi) {
            double x = CGAL::to_double(pt.x());
            double y = CGAL::to_double(pt.y());
            minX = std::min(minX, x);
            maxX = std::max(maxX, x);
            minY = std::min(minY, y);
            maxY = std::max(maxY, y);
        }
        double padX = (maxX - minX) * 0.15;
        double padY = (maxY - minY) * 0.15;
        minX -= padX; maxX += padX;
        minY -= padY; maxY += padY;
        double scaleX = (width() - 40) / (maxX - minX);
        double scaleY = (height() - 40) / (maxY - minY);
        scale = std::min(scaleX, scaleY);
        offsetX = 20 - minX * scale;
        offsetY = height() - 20 - minY * scale;
    }

    void resizeEvent(QResizeEvent*) override { computeTransform(); }

    void paintEvent(QPaintEvent*) override {
        QPainter p(this);
        p.setRenderHint(QPainter::Antialiasing);
        p.fillRect(rect(), Qt::white);

        auto transform = [&](const Point& pt) -> QPointF {
            return QPointF(
                CGAL::to_double(pt.x()) * scale + offsetX,
                CGAL::to_double(pt.y()) * scale + offsetY
            );
        };

        if (Gi.empty()) return;

        // Draw polygon
        p.setPen(Qt::blue);
        p.setBrush(QBrush(QColor(100, 149, 237, 80)));
        QPolygonF poly;
        for (const auto& pt : Gi) poly.append(transform(pt));
        poly.append(poly[0]);
        p.drawPolyline(poly);

        // Highlight non-convex vertices
        for (int i = 0; i < (int)Gi.size(); i++) {
            const Point& a = Gi[i];
            const Point& b = Gi[(i + 1) % Gi.size()];
            const Point& c = Gi[(i + 2) % Gi.size()];
            if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
                p.setBrush(Qt::red);
                p.drawEllipse(transform(b), 8, 8);
                p.drawText(transform(b) + QPointF(10, -10),
                          "Vertex " + QString::number((i + 1) % Gi.size()));
            }
        }

        // Draw vertices
        p.setBrush(Qt::blue);
        for (int i = 0; i < (int)Gi.size(); i++) {
            p.drawEllipse(transform(Gi[i]), 3, 3);
        }

        p.setPen(Qt::black);
        p.drawText(10, 20, "Gi vertices: " + QString::number(Gi.size()));
        p.drawText(10, 40, "Convex: " + QString(is_convex(Gi) ? "YES" : "NO"));
        p.drawText(10, 60, "Simple: " + QString(is_simple(Gi) ? "YES" : "NO"));
        if (non_convex_vertex >= 0) {
            p.drawText(10, 80, "RED dot = non-convex vertex " + QString::number(non_convex_vertex));
        }
    }
};

int main(int argc, char* argv[]) {
    std::cout << "=== Testing get_conv_from_grid convexity ===" << std::endl;
#ifdef USE_EXACT_KERNEL
    std::cout << "Kernel: Exact_predicates_exact_constructions_kernel" << std::endl;
#else
    std::cout << "Kernel: Simple_cartesian<double>" << std::endl;
#endif

    // Load trajectory
    auto stream = load_trajectory("/Users/sinchunyeung/UROP1100Q/data/taxi_simplified/1/original.txt");
    if (stream.empty()) {
        std::cerr << "Failed to load trajectory" << std::endl;
        return 1;
    }
    std::cout << "Loaded " << stream.size() << " points" << std::endl;

    // Test get_conv_from_grid on first 50 points
    std::vector<std::vector<Point>> non_convex_Gis;
    for (int i = 0; i < 50 && i < (int)stream.size(); i++) {
        auto Gi = get_conv_from_grid(stream[i]);
        if (!is_convex(Gi)) {
            std::cout << "Point " << i << ": Gi is NON-CONVEX (" << Gi.size() << " vertices)" << std::endl;
            non_convex_Gis.push_back(Gi);

            // Show which vertex is non-convex
            for (int j = 0; j < (int)Gi.size(); j++) {
                const Point& a = Gi[j];
                const Point& b = Gi[(j + 1) % Gi.size()];
                const Point& c = Gi[(j + 2) % Gi.size()];
                if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
                    std::cout << "  Vertex " << (j + 1) << " has RIGHT/COLLINEAR turn" << std::endl;
                }
            }
        }
    }

    std::cout << std::endl;
    std::cout << "Found " << non_convex_Gis.size() << " non-convex Gi out of 50 tested" << std::endl;

    if (!non_convex_Gis.empty()) {
        // Show detailed analysis of first non-convex Gi
        std::cout << std::endl;
        std::cout << "=== First Non-Convex Gi Analysis ===" << std::endl;
        auto& Gi = non_convex_Gis[0];
        std::cout << "Gi has " << Gi.size() << " vertices:" << std::endl;
        for (int i = 0; i < (int)Gi.size(); i++) {
            std::cout << "  " << i << ": (" << CGAL::to_double(Gi[i].x()) 
                      << ", " << CGAL::to_double(Gi[i].y()) << ")";
            if (i > 0 && i < (int)Gi.size() - 1) {
                const Point& a = Gi[i - 1];
                const Point& b = Gi[i];
                const Point& c = Gi[i + 1];
                auto ori = CGAL::orientation(a, b, c);
                std::cout << " [";
                if (ori == CGAL::LEFT_TURN) std::cout << "LEFT";
                else if (ori == CGAL::RIGHT_TURN) std::cout << "RIGHT *** NON-CONVEX";
                else std::cout << "COLLINEAR";
                std::cout << "]";
            }
            std::cout << std::endl;
        }
    }

    // Launch Qt viewer for first non-convex Gi
    QApplication app(argc, argv);
    GiViewer viewer;
    if (!non_convex_Gis.empty()) {
        viewer.setGi(non_convex_Gis[0]);
        viewer.show();
    }

    std::cout << std::endl;
    std::cout << "Close the window to exit." << std::endl;
    return app.exec();
}

