        const Point& c = pts[(i + 2) % n];
        if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
            return false;
        }
    }
    return true;
}

class GiViewer : public QWidget {
public:
    std::vector<Point> stream;
    int current_idx = 0;
    std::vector<Point> Gi;
    double scale = 1.0;
    double offsetX = 0, offsetY = 0;

    GiViewer(QWidget* parent = nullptr) : QWidget(parent) {
        setMinimumSize(900, 600);
        setWindowTitle("get_conv_from_grid Visualization");
    }

    void setStream(const std::vector<Point>& s) {
        stream = s;
        if (!stream.empty()) {
            current_idx = 0;
            updateGi();
        }
    }

    void updateGi() {
        if (current_idx >= 0 && current_idx < (int)stream.size()) {
            Gi = get_conv_from_grid(stream[current_idx]);
            computeTransform();
            update();
        }
    }

    void computeTransform() {
        double minX = 1e100, maxX = -1e100;
        double minY = 1e100, maxY = -1e100;

        // Include p0 and Gi in bounds
        if (current_idx >= 0 && current_idx < (int)stream.size()) {
            double px = CGAL::to_double(stream[current_idx].x());
            double py = CGAL::to_double(stream[current_idx].y());
            double r = R_val();
            minX = px - r - 20; maxX = px + r + 20;
            minY = py - r - 20; maxY = py + r + 20;
        }

        for (const auto& pt : Gi) {
            double x = CGAL::to_double(pt.x());
            double y = CGAL::to_double(pt.y());
            minX = std::min(minX, x);
            maxX = std::max(maxX, x);
            minY = std::min(minY, y);
            maxY = std::max(maxY, y);
        }

        double scaleX = (width() - 40) / (maxX - minX);
        double scaleY = (height() - 40) / (maxY - minY);
        scale = std::min(scaleX, scaleY);

        offsetX = 20 - minX * scale;
        offsetY = height() - 20 - minY * scale;
    }

    void resizeEvent(QResizeEvent*) override { computeTransform(); }

    void paintEvent(QPaintEvent*) override {
        QPainter p(this);
        p.setRenderHint(QPainter::Antialiasing);
        p.fillRect(rect(), Qt::white);

        if (stream.empty() || current_idx < 0 || current_idx >= (int)stream.size()) return;

        auto transform = [&](const Point& pt) -> QPointF {
            return QPointF(
                CGAL::to_double(pt.x()) * scale + offsetX,
                CGAL::to_double(pt.y()) * scale + offsetY
            );
        };

        const Point& p0 = stream[current_idx];
        double px = CGAL::to_double(p0.x());
        double py = CGAL::to_double(p0.y());
        double r = R_val();

        // Draw circle (radius = R)
        p.setPen(QPen(Qt::gray, 1, Qt::DashLine));
        QPointF center = transform(p0);
        p.drawEllipse(center, r * scale, r * scale);

        // Draw grid lines
        p.setPen(QPen(Qt::lightGray, 0.5));
        for (double x = floor((px - r) / DELTA) * DELTA; x <= px + r; x += DELTA) {
            QPointF start(x, py - r);
            QPointF end(x, py + r);
            p.drawLine(transform(start), transform(end));
        }
        for (double y = floor((py - r) / DELTA) * DELTA; y <= py + r; y += DELTA) {
            QPointF start(px - r, y);
            QPointF end(px + r, y);
            p.drawLine(transform(start), transform(end));
        }

        // Draw Gi polygon (blue)
        if (!Gi.empty()) {
            p.setPen(Qt::blue);
            p.setBrush(QBrush(QColor(100, 149, 237, 100)));
            QPolygonF polyGi;
            for (const auto& pt : Gi) {
                polyGi.append(transform(pt));
            }
            polyGi.append(polyGi[0]);
            p.drawPolyline(polyGi);
        }

        // Draw center point p0 (red)
        p.setBrush(Qt::red);
        p.drawEllipse(center, 6, 6);

        // Draw vertex labels
        p.setPen(Qt::blue);
        p.setBrush(Qt::blue);
        for (int i = 0; i < (int)Gi.size(); i++) {
            QPointF pt = transform(Gi[i]);
            p.drawEllipse(pt, 3, 3);
            if (Gi.size() <= 20) {
                p.drawText(pt + QPointF(5, -5), QString::number(i));
            }
        }

        // Info text
        p.setPen(Qt::black);
        p.drawText(10, 20, "Point " + QString::number(current_idx) + " / " + QString::number(stream.size()) +
                   "  [Left/Right to navigate, Up/Down by 10]");
        p.drawText(10, 40, "p0 = (" + QString::number(px, 'f', 2) + ", " + QString::number(py, 'f', 2) + ")");
        p.drawText(10, 60, "R = " + QString::number(r, 'f', 2) + ", GRID = " + QString::number(GRID_val(), 'f', 2));
        p.drawText(10, 80, "Gi vertices: " + QString::number(Gi.size()));
        p.drawText(10, 100, "Convex: " + QString(is_convex(Gi) ? "YES" : "NO"));

        // Check for non-convex (should never happen with current code)
        for (int i = 0; i < (int)Gi.size(); i++) {
            const Point& a = Gi[i];
            const Point& b = Gi[(i + 1) % Gi.size()];
            const Point& c = Gi[(i + 2) % Gi.size()];
            if (CGAL::orientation(a, b, c) != CGAL::LEFT_TURN) {
                p.setBrush(Qt::red);
                p.drawEllipse(transform(b), 10, 10);
                p.drawText(10, 120, "WARNING: Non-convex vertex found!");
                break;
            }
        }
    }

    void keyPressEvent(QKeyEvent* event) override {
        if (event->key() == Qt::Key_Right) {
            current_idx = std::min(current_idx + 1, (int)stream.size() - 1);
            updateGi();
        } else if (event->key() == Qt::Key_Left) {
            current_idx = std::max(current_idx - 1, 0);
            updateGi();
        } else if (event->key() == Qt::Key_Down) {
            current_idx = std::min(current_idx + 10, (int)stream.size() - 1);
            updateGi();
        } else if (event->key() == Qt::Key_Up) {
            current_idx = std::max(current_idx - 10, 0);
            updateGi();
        }
    }
};

