    int convex_count = 0;
    int non_convex_count = 0;
    for (int i = 0; i < (int)stream.size(); i++) {
        auto Gi = get_conv_from_grid(stream[i]);
        if (is_convex(Gi)) convex_count++;
        else non_convex_count++;
