        std::cout << "-----------------------------|-------------|--------|--------|----------\n";

        auto print_row = [&](const char* name, Duration dur, long long calls) {
            auto ms = std::chrono::duration<double, std::milli>(dur).count();
            double pct = total_ms > 0 ? (ms / total_ms) * 100 : 0;
            double ms_per_call = calls > 0 ? ms / calls : 0;
            std::cout << std::setw(28) << std::left << name << " | "
                      << std::setw(10) << std::right << ms << " | "
                      << std::setw(6) << std::fixed << std::setprecision(1) << pct << "% | "
                      << std::setw(6) << calls << " | "
                      << std::setprecision(4) << ms_per_call << "\n";
        };

        print_row("get_points_from_grid", get_points_from_grid, get_points_from_grid_calls);
        print_row("get_conv_from_grid", get_conv_from_grid, get_conv_from_grid_calls);
        print_row("find_F", find_F, find_F_calls);
        print_row("polygon_construct", polygon_construct, polygon_construct_calls);
        print_row("convex_intersection", convex_intersection, convex_intersection_calls);
        print_row("CGAL::intersection", cgal_intersection, cgal_intersection_calls);
        print_row("validation", validation, 1);
        print_row("loop_overhead", loop_overhead, 1);
        std::cout << "-----------------------------|-------------|--------|--------|----------\n";
        std::cout << std::setw(28) << std::left << "TOTAL" << " | "
