// Compare convex_polygon_intersection vs CGAL::intersection on real data
// Grabs actual F and Gi polygons from simplify.cpp execution

#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <cmath>
#include <algorithm>
#include <set>
#include <iomanip>

#include "kernel.h"

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;

double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }

std::vector<Point> load_trajectory(const std::string& path) {
    std::ifstream fin(path);
    if (!fin) return {};
    int N;
    fin >> N;
    std::vector<Point> stream;
    for (int i = 0; i < N; i++) {
        double x, y;
        fin >> x >> y;
        stream.emplace_back(x, y);
    }
    return stream;
}

// ===== Functions from simplify.cpp =====

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> points;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        const int x_max = -x_min;
        for (int x = x_min; x <= x_max; x++) {
            points.emplace_back(px + x * GRID, py + y_actual);
        }
    }
    return points;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x());
    const double py = CGAL::to_double(p.y());
    const double r = R_val();
    const double GRID = GRID_val();
    const double r2 = r * r;
    int y_min = -(r / GRID) - 1;
    int y_max = -y_min;
    std::vector<Point> boundaries;
    boundaries.reserve(2 * y_max + 1);
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0)
            boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

std::vector<Point> current_bbox() {
    return {{-10000, -10000}, {10000, -10000}, {10000, 10000}, {-10000, 10000}};
}

std::vector<Point> find_F(const Point& p0, const std::vector<Point>& S) {
    std::vector<Point> result;
    const Bbox& bbox = current_bbox()[0].bbox() + current_bbox()[1].bbox() +
                       current_bbox()[2].bbox() + current_bbox()[3].bbox();
    if (S.size() < 2) {
        Rect R(Point(bbox.xmin(), bbox.ymin()), Point(bbox.xmax(), bbox.ymax()));
        result = {R.min(), Point(R.max().x(), R.min().y()),
                  R.max(), Point(R.min().x(), R.max().y())};
    } else {
        Rect R0(S[0].bbox());
        for (size_t i = 1; i < S.size(); i++) {
            R0 = R0 + S[i].bbox();
        }
        R0 = R0 + p0.bbox();
        R0 = R0 + Point(bbox.xmin() - R0.xmin() + R0.xmax(), bbox.ymin() - R0.ymin() + R0.ymax());
        result = {R0.min(), Point(R0.max().x(), R0.min().y()),
                  R0.max(), Point(R0.min().x(), R0.max().y())};
    }
    return result;
}

// ===== Point in convex polygon (from simplify.cpp) =====
bool point_in_convex(const Point& query, const std::vector<Point>& convex, bool strict) {
    int n = convex.size();
    for (int i = 0; i < n; i++) {
        const Point& a = convex[i];
        const Point& b = convex[(i + 1) % n];
        double orient = CGAL::to_double(CGAL::orientation(a, b, query));
        if (strict && orient <= 0) return false;
        if (!strict && orient < 0) return false;
    }
    return true;
}

// ===== Convex polygon intersection (O'Rourke's algorithm from simplify.cpp) =====
std::vector<Point> convex_polygon_intersection(const std::vector<Point>& P_input,
                                                 const std::vector<Point>& Q_input) {
    if (P_input.empty() || Q_input.empty()) return {};

    std::vector<Point> P = P_input;
    std::vector<Point> Q = Q_input;

    auto less_x = [](const Point& a, const Point& b) {
        double ax = CGAL::to_double(a.x()), ay = CGAL::to_double(a.y());
        double bx = CGAL::to_double(b.x()), by = CGAL::to_double(b.y());
        return ax < bx || (ax == bx && ay < by);
    };

    std::sort(P.begin(), P.end(), less_x);
    std::sort(Q.begin(), Q.end(), less_x);

    auto eq_x = [](const Point& a, const Point& b) {
        return CGAL::to_double(a.x()) == CGAL::to_double(b.x()) &&
               CGAL::to_double(a.y()) == CGAL::to_double(b.y());
    };

    P.erase(std::unique(P.begin(), P.end(), eq_x), P.end());
    Q.erase(std::unique(Q.begin(), Q.end(), eq_x), Q.end());

    int n = P.size(), m = Q.size();
    if (n < 3 || m < 3) return {};

    bool all_P_in_Q = true;
    bool all_Q_in_P = true;
    for (const auto& p : P) {
        if (!point_in_convex(p, Q, true)) {
            all_P_in_Q = false;
            break;
        }
    }
    if (all_P_in_Q) return P;

    for (const auto& q : Q) {
        if (!point_in_convex(q, P, true)) {
            all_Q_in_P = false;
            break;
        }
    }
    if (all_Q_in_P) return Q;

    if (CGAL::area(Kernel::Point_2(0,0), P[0], P[1]) < 0)
        std::reverse(P.begin(), P.end());
    if (CGAL::area(Kernel::Point_2(0,0), Q[0], Q[1]) < 0)
        std::reverse(Q.begin(), Q.end());

    int i = 0, j = 0;
    std::vector<Point> result;
    bool first_intersection_found = false;
    Point first_intersection;
    Point prevP = P[n-1], prevQ = Q[m-1];

    for (int k = 0; k < n + m; k++) {
        result.push_back((i < n) ? P[i % n] : P[i % n]);
        if (k % 2 == 0) {
            if (CGAL::orientation(prevQ, Q[j % m], P[i % n]) >= 0) {
                prevP = P[i % n];
                i++;
            } else {
                prevQ = Q[j % m];
                j++;
            }
        } else {
            if (CGAL::orientation(prevP, P[i % n], Q[j % m]) <= 0) {
                prevQ = Q[j % m];
                j++;
            } else {
                prevP = P[i % n];
                i++;
            }
        }
    }

    return result;
}

// ===== Helper functions =====

bool polygons_equal(const std::vector<Point>& A, const std::vector<Point>& B, double tol = 1e-6) {
    if (A.size() != B.size()) return false;
    int n = A.size();
    for (int offset = 0; offset < n; offset++) {
        bool match = true;
        for (int i = 0; i < n; i++) {
            const Point& a = A[i];
            const Point& b = B[(i + offset) % n];
            if (std::abs(CGAL::to_double(a.x()) - CGAL::to_double(b.x())) > tol ||
                std::abs(CGAL::to_double(a.y()) - CGAL::to_double(b.y())) > tol) {
                match = false;
                break;
            }
        }
        if (match) return true;
    }
    return false;
}

bool polygon_contains(const std::vector<Point>& container, const std::vector<Point>& target, double tol = 1e-3) {
    if (container.empty() || target.empty()) return false;
    for (const auto& pt : target) {
        if (!point_in_convex(pt, container, true)) {
            return false;
        }
    }
    return true;
}

double polygon_area(const std::vector<Point>& poly) {
    double area = 0;
    int n = poly.size();
    for (int i = 0; i < n; i++) {
        const Point& a = poly[i];
        const Point& b = poly[(i + 1) % n];
        area += CGAL::to_double(a.x()) * CGAL::to_double(b.y()) -
                CGAL::to_double(b.x()) * CGAL::to_double(a.y());
    }
    return std::abs(area) / 2.0;
}

void print_polygon(const std::string& name, const std::vector<Point>& poly) {
    std::cout << name << " (" << poly.size() << " vertices):\n";
    for (const auto& p : poly) {
        std::cout << "  (" << CGAL::to_double(p.x()) << ", " << CGAL::to_double(p.y()) << ")\n";
    }
}

