    int both_similar = 0;  // Same area, one may have extra collinear points
    int convex_smaller = 0;  // Convex is proper subset
    int cgal_smaller = 0;    // CGAL is proper subset
    int disjoint = 0;        // Different results (neither contains the other)
    int cgal_errors = 0;
    int convex_errors = 0;

    std::vector<std::tuple<std::vector<Point>, std::vector<Point>, std::vector<Point>, std::vector<Point>>> mismatches;

    // Sample a subset of points to test (full run would be too slow)
    int max_tests = 1000;
    int step = std::max(1, (int)stream.size() / max_tests);

    std::cout << "Testing with step " << step << " (max " << max_tests << " tests)...\n";
    std::cout << std::fixed << std::setprecision(4);

    for (int test_idx = 0; test_idx < (int)stream.size() && total_tests < max_tests; test_idx += step) {
        const Point& p0 = stream[test_idx];

        // Get P (grid points around p0)
        std::vector<Point> P = get_points_from_grid(p0);
        if (P.empty()) continue;

        // For each grid point in P, simulate S and compute F, Gi
        for (int pi_idx = 0; pi_idx < (int)P.size() && total_tests < max_tests; pi_idx += std::max(1, (int)P.size() / 10)) {
            const Point& pi = P[pi_idx];

            // Simulate S with just p0 and pi
            std::vector<Point> S = {p0, pi};

            // Compute F and Gi
            std::vector<Point> F = find_F(p0, S);
            std::vector<Point> Gi = get_conv_from_grid(pi);

            // Skip degenerate cases
            if (F.size() < 3 || Gi.size() < 3) continue;

            total_tests++;

            // Get CGAL intersection result
            std::vector<Point> cgal_result;
            try {
                Polygon F_poly(F.begin(), F.end());
                Polygon Gi_poly(Gi.begin(), Gi.end());
                std::vector<Polygon_with_holes> result;
                CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));
                if (!result.empty() && !result[0].outer_boundary().is_empty()) {
                    for (auto it = result[0].outer_boundary().vertices_begin();
                         it != result[0].outer_boundary().vertices_end(); ++it) {
                        cgal_result.push_back(*it);
                    }
                }
            } catch (const std::exception& e) {
                cgal_errors++;
                continue;
            }

            // Get convex intersection result
            std::vector<Point> convex_result;
            try {
                convex_result = convex_polygon_intersection(F, Gi);
            } catch (const std::exception& e) {
                convex_errors++;
                continue;
            }

            // Compare results
            bool cgal_empty = cgal_result.size() < 3;
            bool convex_empty = convex_result.size() < 3;

            if (cgal_empty && convex_empty) {
                both_empty++;
                continue;
            }

            if (polygons_equal(cgal_result, convex_result)) {
                both_equal++;
                continue;
            }

            double cgal_area = polygon_area(cgal_result);
            double convex_area = polygon_area(convex_result);

            // Check containment
            bool cgal_contains_convex = polygon_contains(cgal_result, convex_result);
            bool convex_contains_cgal = polygon_contains(convex_result, cgal_result);

            if (cgal_contains_convex && convex_contains_cgal) {
                both_equal++;  // Same area, just different vertex ordering
                continue;
            }

            if (cgal_contains_convex && convex_area > 0) {
                convex_smaller++;
                mismatches.push_back({F, Gi, cgal_result, convex_result});
                continue;
            }

            if (convex_contains_cgal && cgal_area > 0) {
                cgal_smaller++;
                mismatches.push_back({F, Gi, cgal_result, convex_result});
                continue;
            }

            // Disjoint or partially overlapping
            disjoint++;
            if (mismatches.size() < 10) {
                mismatches.push_back({F, Gi, cgal_result, convex_result});
            }
        }
    }

    // Print results
    std::cout << "\n========== RESULTS ==========\n";
    std::cout << "Total tests: " << total_tests << "\n";
    std::cout << "CGAL errors: " << cgal_errors << "\n";
    std::cout << "Convex errors: " << convex_errors << "\n";
    std::cout << "\n--- Comparison ---\n";
    std::cout << "Both empty: " << both_empty << " (" << (100.0 * both_empty / total_tests) << "%)\n";
    std::cout << "Equal: " << both_equal << " (" << (100.0 * both_equal / total_tests) << "%)\n";
    std::cout << "Convex subset of CGAL: " << convex_smaller << " (" << (100.0 * convex_smaller / total_tests) << "%)\n";
    std::cout << "CGAL subset of Convex: " << cgal_smaller << " (" << (100.0 * cgal_smaller / total_tests) << "%)\n";
    std::cout << "Disjoint: " << disjoint << " (" << (100.0 * disjoint / total_tests) << "%)\n";

    int consistent = both_empty + both_equal + convex_smaller + cgal_smaller;
    std::cout << "\n*** Consistent (one contains other or both empty): " << consistent
              << " (" << (100.0 * consistent / total_tests) << "%) ***\n";
    std::cout << "*** Inconsistent: " << disjoint << " (" << (100.0 * disjoint / total_tests) << "%) ***\n";

    // Print first few mismatches
    if (!mismatches.empty()) {
        std::cout << "\n========== SAMPLE MISMATCHES ==========\n";
        for (size_t i = 0; i < std::min((size_t)3, mismatches.size()); i++) {
            auto& [F, Gi, cgal_res, convex_res] = mismatches[i];
            std::cout << "\n--- Mismatch " << (i + 1) << " ---\n";
            std::cout << "F: " << F.size() << " vertices\n";
            std::cout << "Gi: " << Gi.size() << " vertices\n";
            std::cout << "CGAL result: " << cgal_res.size() << " vertices, area=" << polygon_area(cgal_res) << "\n";
            std::cout << "Convex result: " << convex_res.size() << " vertices, area=" << polygon_area(convex_res) << "\n";

            if (cgal_res.size() > 0 && cgal_res.size() <= 20) {
                print_polygon("CGAL", cgal_res);
            }
            if (convex_res.size() > 0 && convex_res.size() <= 20) {
                print_polygon("Convex", convex_res);
            }
        }
    }

    return 0;
}

