        return 1;
    }
    std::cout << "Loaded " << stream.size() << " trajectory points\n\n";

    int total_tests = 0;
    int both_empty = 0;
    int both_equal = 0;
    int convex_smaller = 0;
    int cgal_smaller = 0;
    int disjoint = 0;
    int cgal_errors = 0;

    std::vector<std::tuple<std::vector<Point>, std::vector<Point>, std::vector<Point>, std::vector<Point>>> mismatches;

    int max_tests = 500;
    int step = std::max(1, (int)stream.size() / max_tests);

    std::cout << "Testing up to " << max_tests << " pairs...\n";
    std::cout << std::fixed << std::setprecision(2);

    for (int test_idx = 0; test_idx < (int)stream.size() && total_tests < max_tests; test_idx += step) {
        const Point& p0 = stream[test_idx];
        std::vector<Point> P = get_points_from_grid(p0);
