            std::vector<Point> Gi = get_conv_from_grid(pi);

            if (F.size() < 3 || Gi.size() < 3) continue;

            total_tests++;

            // CGAL result
            std::vector<Point> cgal_result;
            try {
                Polygon F_poly(F.begin(), F.end());
                Polygon Gi_poly(Gi.begin(), Gi.end());
                std::vector<Polygon_with_holes> result;
                CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));
                if (!result.empty() && !result[0].outer_boundary().is_empty()) {
                    for (auto it = result[0].outer_boundary().vertices_begin();
                         it != result[0].outer_boundary().vertices_end(); ++it) {
                        cgal_result.push_back(*it);
                    }
                }
            } catch (const std::exception& e) {
                cgal_errors++;
                continue;
            }

            // Convex result
            std::vector<Point> convex_result = convex_polygon_intersection(F, Gi);

            bool cgal_empty = cgal_result.size() < 3;
            bool convex_empty = convex_result.size() < 3;

            if (cgal_empty && convex_empty) {
                both_empty++;
                continue;
            }

            if (polygons_equal(cgal_result, convex_result)) {
                both_equal++;
                continue;
            }

            double cgal_area = polygon_area(cgal_result);
            double convex_area = polygon_area(convex_result);

            // Check containment
            bool cgal_contains_convex = point_in_convex(cgal_result.empty() ? Point(0,0) : cgal_result[0], convex_result, true);
            bool convex_contains_cgal = point_in_convex(convex_result.empty() ? Point(0,0) : convex_result[0], cgal_result, true);

            // Simplified check: if areas match within 1%, consider equal
            if (std::abs(cgal_area - convex_area) / std::max(cgal_area, convex_area, 1.0) < 0.01) {
                both_equal++;
                continue;
            }

            if (cgal_area < convex_area * 0.99) {
                convex_smaller++;
            } else if (convex_area < cgal_area * 0.99) {
                cgal_smaller++;
            } else {
                disjoint++;
            }

            if (mismatches.size() < 5) {
                mismatches.push_back({F, Gi, cgal_result, convex_result});
            }
        }
    }

    std::cout << "\n========== RESULTS ==========\n";
    std::cout << "Total tests: " << total_tests << "\n";
    std::cout << "CGAL errors: " << cgal_errors << "\n\n";
    std::cout << "--- Comparison ---\n";
    std::cout << "Both empty: " << both_empty << " (" << (100.0 * both_empty / total_tests) << "%)\n";
    std::cout << "Equal (within 1% area): " << both_equal << " (" << (100.0 * both_equal / total_tests) << "%)\n";
    std::cout << "Convex smaller: " << convex_smaller << " (" << (100.0 * convex_smaller / total_tests) << "%)\n";
    std::cout << "CGAL smaller: " << cgal_smaller << " (" << (100.0 * cgal_smaller / total_tests) << "%)\n";
    std::cout << "Disjoint: " << disjoint << " (" << (100.0 * disjoint / total_tests) << "%)\n";

    int consistent = both_empty + both_equal;
    std::cout << "\n*** Consistent (equal or both empty): " << consistent
              << " (" << (100.0 * consistent / total_tests) << "%) ***\n";
    std::cout << "*** Inconsistent: " << (total_tests - consistent) << " (" << (100.0 * (total_tests - consistent) / total_tests) << "%) ***\n";

    if (!mismatches.empty()) {
        std::cout << "\n========== SAMPLE MISMATCHES ==========\n";
        for (size_t i = 0; i < std::min((size_t)3, mismatches.size()); i++) {
            auto& [F, Gi, cgal_res, convex_res] = mismatches[i];
            std::cout << "\n--- Mismatch " << (i + 1) << " ---\n";
            std::cout << "F: " << F.size() << " vertices\n";
            std::cout << "Gi: " << Gi.size() << " vertices\n";
            std::cout << "CGAL: " << cgal_res.size() << " vertices, area=" << polygon_area(cgal_res) << "\n";
            std::cout << "Convex: " << convex_res.size() << " vertices, area=" << polygon_area(convex_res) << "\n";
            if (!cgal_res.empty()) print_polygon("CGAL", cgal_res);
            if (!convex_res.empty()) print_polygon("Convex", convex_res);
        }
    }

    return 0;
}

