// Check if CGAL and Convex return first vertex differently
#define USE_EXACT_KERNEL 1

#include "kernel.h"
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <fstream>
#include <cmath>
#include <algorithm>
#include <iomanip>

using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using Polygon_with_holes = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;
double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }
constexpr double BMIN = -10000.0, BMAX = 10000.0;

std::vector<Point> load_trajectory(const std::string& path) {
    std::ifstream fin(path);
    if (!fin) return {};
    int N; fin >> N;
    std::vector<Point> stream;
    for (int i = 0; i < N; i++) {
        double x, y; fin >> x >> y;
        stream.emplace_back(x, y);
    }
    return stream;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    const double r = R_val(), GRID = GRID_val(), r2 = r * r;
    int y_min = -(r / GRID) - 1, y_max = -y_min;
    std::vector<Point> boundaries;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0) boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv; conv.reserve(boundaries.size());
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

std::vector<Point> current_bbox() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX), Point(BMIN, BMAX)};
}

std::vector<Point> find_F(const Point& p0, const std::vector<Point>& S) {
    if (S.size() < 2) return current_bbox();
    double min_x = CGAL::to_double(p0.x()), min_y = CGAL::to_double(p0.y());
    double max_x = min_x, max_y = min_y;
    for (const auto& p : S) {
        min_x = std::min(min_x, CGAL::to_double(p.x()));
        min_y = std::min(min_y, CGAL::to_double(p.y()));
        max_x = std::max(max_x, CGAL::to_double(p.x()));
        max_y = std::max(max_y, CGAL::to_double(p.y()));
    }
    double center_x = (min_x + max_x) / 2.0, center_y = (min_y + max_y) / 2.0;
    double half_width = BMAX - center_x, half_height = BMAX - center_y;
    return {
        Point(center_x - half_width, center_y - half_height),
        Point(center_x + half_width, center_y - half_height),
        Point(center_x + half_width, center_y + half_height),
        Point(center_x - half_width, center_y + half_height)
    };
}

bool point_in_convex(const Point &p, const std::vector<Point> &poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto &a = poly[i], &b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN)) return false;
    }
    return true;
}

std::vector<Point> convex_polygon_intersection(const std::vector<Point>& P_input, const std::vector<Point>& Q_input) {
    if (P_input.empty() || Q_input.empty()) return {};
    std::vector<Point> P = P_input, Q = Q_input;
    if (CGAL::area(Kernel::Point_2(0,0), P[0], P[1]) < 0) std::reverse(P.begin(), P.end());
    if (CGAL::area(Kernel::Point_2(0,0), Q[0], Q[1]) < 0) std::reverse(Q.begin(), Q.end());
    int n = P.size(), m = Q.size();
    if (n < 3 || m < 3) return {};
    bool all_P_in_Q = true, all_Q_in_P = true;
    for (const auto& p : P) { if (!point_in_convex(p, Q, true)) { all_P_in_Q = false; break; } }
    if (all_P_in_Q) return P;
    for (const auto& q : Q) { if (!point_in_convex(q, P, true)) { all_Q_in_P = false; break; } }
    if (all_Q_in_P) return Q;
    int i = 0, j = 0;
    std::vector<Point> result;
    bool first_intersection_found = false; Point first_intersection;
    int max_iter = 2 * (n + m) + 10, iter = 0;
    auto cross = [](const Point& o, const Point& a, const Point& b) {
        return (CGAL::to_double(a.x()) - CGAL::to_double(o.x())) * (CGAL::to_double(b.y()) - CGAL::to_double(o.y())) -
               (CGAL::to_double(a.y()) - CGAL::to_double(o.y())) * (CGAL::to_double(b.x()) - CGAL::to_double(o.x()));
    };
    auto advance_i = [&]() { i = (i + 1) % n; };
    auto advance_j = [&]() { j = (j + 1) % m; };
    auto segments_intersect = [&](const Point& a1, const Point& a2, const Point& b1, const Point& b2) -> std::optional<Point> {
        double x1 = CGAL::to_double(a1.x()), y1 = CGAL::to_double(a1.y());
        double x2 = CGAL::to_double(a2.x()), y2 = CGAL::to_double(a2.y());
        double x3 = CGAL::to_double(b1.x()), y3 = CGAL::to_double(b1.y());
        double x4 = CGAL::to_double(b2.x()), y4 = CGAL::to_double(b2.y());
        double denom = (x1 - x2) * (y3 - y4) - (y1 - y2) * (x3 - x4);
        if (std::abs(denom) < 1e-12) return std::nullopt;
        double t = ((x1 - x3) * (y3 - y4) - (y1 - y3) * (x3 - x4)) / denom;
        double u = -((x1 - x2) * (y1 - y3) - (y1 - y2) * (x1 - x3)) / denom;
        if (t >= -1e-12 && t <= 1.0 + 1e-12 && u >= -1e-12 && u <= 1.0 + 1e-12)
            return Point(x1 + t * (x2 - x1), y1 + t * (y2 - y1));
        return std::nullopt;
    };
    while (iter++ < max_iter) {
        const Point& pi = P[i], &pj = Q[j];
        const Point& p_next_i = P[(i + 1) % n], &p_next_j = Q[(j + 1) % m];
        if (point_in_convex(pi, Q, true)) result.push_back(pi);
        if (point_in_convex(pj, P, true)) result.push_back(pj);
        auto inter = segments_intersect(pi, p_next_i, pj, p_next_j);
        if (inter) {
            if (!first_intersection_found) { first_intersection = *inter; first_intersection_found = true; }
            else {
                double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, first_intersection)));
                if (dist < 1e-6 && result.size() > 2) {
                    if (result.empty() || std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > 1e-6) result.push_back(*inter);
                    break;
                }
            }
            if (result.empty() || std::sqrt(CGAL::to_double(CGAL::squared_distance(*inter, result.back()))) > 1e-6) result.push_back(*inter);
        }
        double c1 = cross(pi, p_next_i, pj), c2 = cross(pj, p_next_j, pi);
        if (std::abs(c1) < 1e-12 && std::abs(c2) < 1e-12) { advance_i(); advance_j(); }
        else if (c1 >= 0 && c2 >= 0) { if (c1 <= c2) advance_i(); else advance_j(); }
        else if (c1 >= 0) advance_i(); else advance_j();
        if (i == 0 && j == 0 && iter > n + m) break;
    }
    if (result.size() > 1) {
        std::vector<Point> deduped; deduped.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            double dist = std::sqrt(CGAL::to_double(CGAL::squared_distance(result[k], deduped.back())));
            if (dist > 1e-6) deduped.push_back(result[k]);
        }
        result = deduped;
    }
    if (result.size() > 2) {
        std::vector<Point> clean; clean.push_back(result[0]);
        for (size_t k = 1; k < result.size(); k++) {
            const Point& prev = clean.back(), &curr = result[k], &next = result[(k + 1) % result.size()];
            double area = CGAL::to_double(CGAL::area(prev, curr, next));
            if (std::abs(area) > 1e-10) clean.push_back(curr);
        }
        result = clean;
    }
    return result;
}

bool same_point(const Point& a, const Point& b, double tol = 1e-6) {
    return std::abs(CGAL::to_double(a.x()) - CGAL::to_double(b.x())) < tol &&
           std::abs(CGAL::to_double(a.y()) - CGAL::to_double(b.y())) < tol;
}

double polygon_area(const std::vector<Point>& poly) {
    if (poly.size() < 3) return 0;
    double area = 0;
    for (size_t i = 0; i < poly.size(); i++) {
        const Point& a = poly[i], &b = poly[(i + 1) % poly.size()];
        area += CGAL::to_double(a.x()) * CGAL::to_double(b.y()) - CGAL::to_double(b.x()) * CGAL::to_double(a.y());
    }
    return std::abs(area) / 2.0;
}

int main() {
    std::cout << "=== Checking first vertex (buffer[1]) differences ===\n\n";
    auto stream = load_trajectory("/Users/sinchunyeung/UROP1100Q/data/taxi_simplified/1/original.txt");
    std::cout << "Loaded " << stream.size() << " points\n\n";

    // Check first simplification step
    const Point& p0 = stream[0];
    std::vector<Point> S = {p0};  // Start with just p0

    int first_diff_step = -1;
    Point diff_cgal, diff_conv;

    for (int step = 0; step < 100 && step < (int)stream.size(); step++) {
        const Point& pi = stream[step];
        std::vector<Point> F = find_F(p0, S);
        std::vector<Point> Gi = get_conv_from_grid(pi);

        // Convex
        std::vector<Point> convex_result = convex_polygon_intersection(F, Gi);

        // CGAL
        std::vector<Point> cgal_result;
        try {
            Polygon F_poly(F.begin(), F.end());
            Polygon Gi_poly(Gi.begin(), Gi.end());
            std::vector<Polygon_with_holes> result;
            CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));
            if (!result.empty() && !result[0].outer_boundary().is_empty()) {
                for (auto it = result[0].outer_boundary().vertices_begin();
                     it != result[0].outer_boundary().vertices_end(); ++it)
                    cgal_result.push_back(*it);
            }
        } catch (...) {}

        // Check first vertex (buffer[1])
        if (convex_result.size() >= 1 && cgal_result.size() >= 1) {
            const Point& conv_first = convex_result[0];
            const Point& cgal_first = cgal_result[0];

            if (!same_point(conv_first, cgal_first)) {
                if (first_diff_step < 0) {
                    first_diff_step = step;
                    diff_cgal = cgal_first;
                    diff_conv = conv_first;
                }
                std::cout << "Step " << step << ": FIRST VERTEX DIFFERS!\n";
                std::cout << "  CGAL first: (" << CGAL::to_double(cgal_first.x()) << ", " << CGAL::to_double(cgal_first.y()) << ")\n";
                std::cout << "  Conv first: (" << CGAL::to_double(conv_first.x()) << ", " << CGAL::to_double(conv_first.y()) << ")\n";
                std::cout << "  CGAL area: " << polygon_area(cgal_result) << "\n";
                std::cout << "  Conv area: " << polygon_area(convex_result) << "\n";

                // Update S with the CGAL result for next iteration
                S = cgal_result;
            } else {
                // Same first vertex, update S
                S = cgal_result;
            }
        } else {
            // Intersection failed
            break;
        }
    }

    std::cout << "\n";
    if (first_diff_step < 0) {
        std::cout << "*** NO DIFFERENCE in first vertices! ***\n";
    } else {
        std::cout << "*** First difference at step " << first_diff_step << " ***\n";
    }

    return 0;
}

// Test why CGAL::intersection fails with Simple_cartesian kernel
// Compare with Exact kernel

#include <CGAL/Polygon_2.h>
