using Kernel = CGAL::Simple_cartesian<double>;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using PolygonHoles = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;
double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }
constexpr double BMIN = -10000.0, BMAX = 10000.0;

std::vector<std::pair<double, double>> load_trajectory(const std::string& path) {
    std::ifstream fin(path);
    if (!fin) return {};
    int N; fin >> N;
    std::vector<std::pair<double, double>> stream;
    for (int i = 0; i < N; i++) {
        double x, y; fin >> x >> y;
        stream.emplace_back(x, y);
    }
    return stream;
}

std::vector<Point> get_points_from_grid(const Point &p) {
    const double px = p.x(), py = p.y();
    const double r = R_val(), GRID = GRID_val(), r2 = r * r;
    int y_min = -(r / GRID) - 1, y_max = -y_min;
    std::vector<Point> points;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        const int x_max = -x_min;
        for (int x = x_min; x <= x_max; x++) {
            points.emplace_back(px + x * GRID, py + y_actual);
        }
    }
    return points;
}

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = p.x(), py = p.y();
    const double r = R_val(), GRID = GRID_val(), r2 = r * r;
    int y_min = -(r / GRID) - 1, y_max = -y_min;
    std::vector<Point> boundaries;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0) boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

std::vector<Point> current_bbox() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX), Point(BMIN, BMAX)};
}

std::vector<Point> find_F(const Point& p0, const std::vector<Point>& S) {
    if (S.size() < 2) return current_bbox();
    double min_x = p0.x(), min_y = p0.y();
    double max_x = min_x, max_y = min_y;
    for (const auto& p : S) {
        min_x = std::min(min_x, p.x());
        min_y = std::min(min_y, p.y());
        max_x = std::max(max_x, p.x());
        max_y = std::max(max_y, p.y());
    }
    double center_x = (min_x + max_x) / 2.0, center_y = (min_y + max_y) / 2.0;
    double half_width = BMAX - center_x, half_height = BMAX - center_y;
    return {
        Point(center_x - half_width, center_y - half_height),
        Point(center_x + half_width, center_y - half_height),
        Point(center_x + half_width, center_y + half_height),
        Point(center_x - half_width, center_y + half_height)
    };
}

// Simulate the actual algorithm with detailed failure tracking
void test_iterative_simplify(const std::vector<std::pair<double,double>>& stream) {
    std::cout << "\n=== Simulating get_longest_stab with INEXACT kernel ===\n";
    std::cout << "Starting with stream[0] = (" << stream[0].first << ", " << stream[0].second << ")\n\n";

    int cur = 0;
    const Point& p0 = Point(stream[0].first, stream[0].second);

    std::vector<Point> P = get_points_from_grid(p0);
    std::cout << "Grid points P: " << P.size() << "\n";

    std::vector<std::vector<Point>> S(P.size(), std::vector<Point>{p0});
    std::vector<int> dead(P.size());

    int iteration = 0;
    int intersection_count = 0;
    int success = 0, fail = 0, segfault = 0;

    while (cur < (int)stream.size()) {
        const Point& pi = Point(stream[cur].first, stream[cur].second);
        std::vector<std::vector<PolygonHoles>> new_S(P.size());

        for (int i = 0; i < (int)P.size(); i++) {
            if (dead[i]) continue;

            std::vector<Point> F = find_F(p0, S[i]);
            std::vector<Point> Gi = get_conv_from_grid(pi);

            Polygon F_poly(F.begin(), F.end());
            Polygon Gi_poly(Gi.begin(), Gi.end());

            intersection_count++;

            try {
                CGAL::intersection(F_poly, Gi_poly, std::back_inserter(new_S[i]));
                success++;

                if (new_S[i].size() == 0) {
                    dead[i] = 1;
                    continue;
                }

                // Update S with result
                S[i].clear();
                for (auto it = new_S[i][0].outer_boundary().vertices_begin();
                     it != new_S[i][0].outer_boundary().vertices_end(); ++it) {
                    S[i].push_back(*it);
                }

            } catch (const std::exception& e) {
                fail++;
                dead[i] = 1;
                if (fail <= 5) {
                    std::cerr << "\n*** EXCEPTION at iteration " << iteration << ", cur=" << cur << ", i=" << i << " ***\n";
                    std::cerr << "  Error: " << e.what() << "\n";
                    std::cerr << "  F.size() = " << F.size() << "\n";
                    std::cerr << "  Gi.size() = " << Gi.size() << "\n";
                    std::cerr << "  F is simple: " << F_poly.is_simple() << "\n";
                    std::cerr << "  Gi is simple: " << Gi_poly.is_simple() << "\n";

                    // Check orientation
                    std::cerr << "  F orientation: " << (F_poly.is_counterclockwise_oriented() ? "CCW" : "CW") << "\n";
                    std::cerr << "  Gi orientation: " << (Gi_poly.is_counterclockwise_oriented() ? "CCW" : "CW") << "\n";

                    // Print first few vertices of F
                    std::cerr << "  F vertices:\n";
                    for (int j = 0; j < std::min(4, (int)F.size()); j++) {
                        std::cerr << "    " << j << ": (" << F[j].x() << ", " << F[j].y() << ")\n";
                    }
                }
            } catch (...) {
                segfault++;
                dead[i] = 1;
                if (segfault <= 3) {
                    std::cerr << "\n*** SIGSEGV at iteration " << iteration << ", cur=" << cur << ", i=" << i << " ***\n";
                }
            }
        }

        int dead_cnt = 0;
        for (int d : dead) if (d) dead_cnt++;

        if (dead_cnt == (int)P.size()) {
            std::cout << "All dead at iteration " << iteration << ", cur=" << cur << "\n";
            break;
        }

        cur++;
        iteration++;

        if (iteration >= 5) {  // Limit for testing
            std::cout << "Stopping after " << iteration << " iterations\n";
            break;
        }
    }

    std::cout << "\nResults:\n";
    std::cout << "  Intersections attempted: " << intersection_count << "\n";
    std::cout << "  Success: " << success << "\n";
    std::cout << "  Exceptions: " << fail << "\n";
    std::cout << "  Segfaults: " << segfault << "\n";
}

