// Focused test: which assertion fails in find_F with Simple_cartesian?
// Compile with: g++ -I/usr/include test_find_F_assert.cpp -o test -lCGAL

#include <CGAL/Simple_cartesian.h>
#include <CGAL/Polygon_2.h>
#include <CGAL/Boolean_set_operations_2.h>
#include <CGAL/convex_hull_2.h>
#include <iostream>
#include <vector>
#include <cmath>

using Kernel = CGAL::Simple_cartesian<double>;
using Point = Kernel::Point_2;
using Polygon = CGAL::Polygon_2<Kernel>;
using PolygonHoles = CGAL::Polygon_with_holes_2<Kernel>;

const double DELTA = 10.0;
const double EPSILON = 20.0;
double R_val() { return 2.0 * EPSILON; }
double GRID_val() { return DELTA; }
constexpr double BMIN = -10000.0, BMAX = 10000.0;

std::vector<Point> get_conv_from_grid(const Point &p) {
    const double px = p.x(), py = p.y();
    const double r = R_val(), GRID = GRID_val(), r2 = r * r;
    int y_min = -(r / GRID) - 1, y_max = -y_min;
    std::vector<Point> boundaries;
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_min = -sqrt(r2 - y_actual * y_actual) / GRID - 1;
        boundaries.emplace_back(px + x_min * GRID, py + y_actual);
    }
    for (int y = y_min; y <= y_max; y++) {
        const double y_actual = y * GRID;
        const int x_max = (sqrt(r2 - y_actual * y_actual) / GRID) + 1;
        if (x_max != 0) boundaries.emplace_back(px + x_max * GRID, py + y_actual);
    }
    std::vector<Point> conv;
    CGAL::convex_hull_2(boundaries.begin(), boundaries.end(), std::back_inserter(conv));
    return conv;
}

bool point_in_convex(const Point &p, const std::vector<Point> &poly, bool ccw = true) {
    for (size_t i = 0, n = poly.size(); i < n; ++i) {
        const auto &a = poly[i];
        const auto &b = poly[(i + 1) % n];
        if (CGAL::orientation(a, b, p) == (ccw ? CGAL::RIGHT_TURN : CGAL::LEFT_TURN))
            return false;
    }
    return true;
}

std::vector<int> find_tangent_idx(const Point &p, const std::vector<Point> &S) {
    int n = S.size();
    std::vector<int> tangent;
    for (int i = 0; i < n; i++) {
        Point pred = S[(i - 1 + n) % n];
        Point now = S[i];
        Point succ = S[(i + 1 + n) % n];
        if (CGAL::orientation(p, pred, now)
                != CGAL::orientation(p, now, succ) &&
            CGAL::orientation(p, now, succ) != CGAL::COLLINEAR) {
            tangent.push_back(i);
        }
    }
    return tangent;
}

enum class Bbox_edge { LEFT, BOTTOM, RIGHT, TOP };

std::optional<Bbox_edge> which_edge(const Point& p) {
    double x = CGAL::to_double(p.x()), y = CGAL::to_double(p.y());
    double eps = 1e-6;
    if (std::abs(x - BMIN) < eps) return Bbox_edge::LEFT;
    if (std::abs(x - BMAX) < eps) return Bbox_edge::RIGHT;
    if (std::abs(y - BMIN) < eps) return Bbox_edge::BOTTOM;
    if (std::abs(y - BMAX) < eps) return Bbox_edge::TOP;
    return std::nullopt;
}

void append_rect_pts(std::vector<Point> &F, Bbox_edge from, Bbox_edge to, bool reverse) {
    std::vector<Bbox_edge> order;
    if (reverse) {
        order = {Bbox_edge::RIGHT, Bbox_edge::TOP, Bbox_edge::LEFT, Bbox_edge::BOTTOM};
    } else {
        order = {Bbox_edge::LEFT, Bbox_edge::TOP, Bbox_edge::RIGHT, Bbox_edge::BOTTOM};
    }
    bool started = false;
    for (auto e : order) {
        if (e == from) started = true;
        if (started) {
            switch (e) {
                case Bbox_edge::LEFT:   F.push_back(Point(BMIN, BMAX)); break;
                case Bbox_edge::TOP:     F.push_back(Point(BMAX, BMAX)); break;
                case Bbox_edge::RIGHT:   F.push_back(Point(BMAX, BMIN)); break;
                case Bbox_edge::BOTTOM:  F.push_back(Point(BMIN, BMIN)); break;
            }
        }
        if (e == to) break;
    }
}

std::optional<Point> intersect_ray_with_rect(const Point& p, const Point& d) {
    double px = CGAL::to_double(p.x()), py = CGAL::to_double(p.y());
    double dx = CGAL::to_double(d.x()) - px, dy = CGAL::to_double(d.y()) - py;

    std::vector<std::pair<double, double>> candidates;

    if (std::abs(dx) > 1e-9) {
        double t1 = (BMIN - px) / dx;
        double ix = BMIN, iy = py + t1 * dy;
        if (t1 > 0 && iy >= BMIN && iy <= BMAX) candidates.emplace_back(t1, ix);

        double t2 = (BMAX - px) / dx;
        double ix2 = BMAX, iy2 = py + t2 * dy;
        if (t2 > 0 && iy2 >= BMIN && iy2 <= BMAX) candidates.emplace_back(t2, ix2);
    }
    if (std::abs(dy) > 1e-9) {
        double t3 = (BMIN - py) / dy;
        double ix3 = px + t3 * dx, iy3 = BMIN;
        if (t3 > 0 && ix3 >= BMIN && ix3 <= BMAX) candidates.emplace_back(t3, iy3);

        double t4 = (BMAX - py) / dy;
        double ix4 = px + t4 * dx, iy4 = BMAX;
        if (t4 > 0 && ix4 >= BMIN && ix4 <= BMAX) candidates.emplace_back(t4, iy4);
    }

    if (candidates.empty()) return std::nullopt;

    std::sort(candidates.begin(), candidates.end());
    double best_t = candidates[0].first;
    return Point(px + best_t * dx, py + best_t * dy);
}

std::vector<Point> current_bbox() {
    return {Point(BMIN, BMIN), Point(BMAX, BMIN), Point(BMAX, BMAX), Point(BMIN, BMAX)};
}

std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    if (S.size() == 1) {
        return current_bbox();
    }
    if (point_in_convex(p, S)) {
        return current_bbox();
    }
    std::vector<int> tangent = find_tangent_idx(p, S);

    // Handle degenerate case: no tangents found
    if (tangent.size() != 2) {
        std::cerr << "  WARN: tangent.size()=" << tangent.size() << " != 2\n";
        return current_bbox();
    }

    std::optional<Point> hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
    std::optional<Point> hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    if (!hit1 || !hit2) {
        std::cerr << "  WARN: hit1=" << (hit1 ? "ok" : "null") << " hit2=" << (hit2 ? "ok" : "null") << "\n";
        return current_bbox();
    }
    std::optional<Bbox_edge> e1 = which_edge(hit1.value());
    std::optional<Bbox_edge> e2 = which_edge(hit2.value());
    if (!e1 || !e2) {
        std::cerr << "  WARN: edge not found\n";
        return current_bbox();
    }

    int n = int(S.size());
    if (tangent[1] - tangent[0] - 1 < 1 && tangent[0] + n - tangent[1] - 1 < 1) {
        std::cerr << "  WARN: polygon too small\n";
        return current_bbox();
    }

    std::vector<Point> F;
    if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]]))  {
        std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1, std::back_inserter(F));
        F.push_back(hit2.value());
        append_rect_pts(F, e2.value(), e1.value(), true);
        F.push_back(hit1.value());
    } else {
        std::copy(S.begin() + tangent[1], S.end(), std::back_inserter(F));
        std::copy(S.begin(), S.begin() + tangent[0] + 1, std::back_inserter(F));
        F.push_back(hit1.value());
        append_rect_pts(F, e1.value(), e2.value(), true);
        F.push_back(hit2.value());
    }

    // Create polygon and check validity
    Polygon poly(F.begin(), F.end());

    if (!poly.is_simple()) {
        std::cerr << "  ERROR: F is NOT simple! is_simple()=false\n";
        std::cerr << "  Points: ";
        for (auto& pt : F) std::cerr << "(" << pt.x() << "," << pt.y() << ") ";
        std::cerr << "\n";
        std::cerr << "  is_counterclockwise_oriented=" << poly.is_counterclockwise_oriented() << "\n";
        std::cerr << "  is_clockwise_oriented=" << poly.is_clockwise_oriented() << "\n";

        // Check for self-intersections
        for (int i = 0; i < (int)F.size(); i++) {
            for (int j = i+2; j < (int)F.size(); j++) {
                if (j == (i + (int)F.size() - 1) % (int)F.size()) continue;
                auto inter = CGAL::intersection(F[i], F[(i+1)%F.size()], F[j], F[(j+1)%F.size()]);
                if (inter) {
                    std::cerr << "  Self-intersection: edge " << i << " vs edge " << j << "\n";
                }
            }
        }

        return current_bbox(); // fallback
    }

    return F;
}

int main() {
    // Test case 1: p0 = first point of trajectory 1
    Point p0(139.88, 2663.55);
    Point pi(139.88, 2673.55);

    std::vector<Point> S = {p0};

    std::cout << "=== Testing find_F failure ===\n";
    std::cout << "p0=(" << p0.x() << "," << p0.y() << ")\n";
    std::cout << "pi=(" << pi.x() << "," << pi.y() << ")\n";

    // Simulate the algorithm
    for (int step = 0; step < 10; step++) {
        std::vector<Point> Gi = get_conv_from_grid(pi);
        Polygon Gi_poly(Gi.begin(), Gi.end());

        std::cout << "\nStep " << step << ": pi=(" << pi.x() << "," << pi.y() << ")\n";
        std::cout << "  S.size()=" << S.size() << ", Gi.size()=" << Gi.size() << "\n";
        std::cout << "  Gi simple=" << Gi_poly.is_simple() << "\n";

        std::vector<Point> F = find_F(p0, S);

        Polygon F_poly(F.begin(), F.end());
        std::cout << "  F simple=" << F_poly.is_simple() << " ccw=" << F_poly.is_counterclockwise_oriented() << "\n";

        if (!F_poly.is_simple() || !Gi_poly.is_simple()) {
            std::cout << "  SKIP intersection - polygon not simple\n";
            break;
        }

        std::cout << "  Calling CGAL::intersection(F, Gi)...\n";
        std::vector<PolygonHoles> result;
        try {
            CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));
            std::cout << "  SUCCESS: result.size()=" << result.size() << "\n";

            if (result.size() == 1) {
                S.clear();
                for (auto it = result[0].outer_boundary().vertices_begin();
                     it != result[0].outer_boundary().vertices_end(); ++it) {
                    S.push_back(*it);
                }
            }
        } catch (const std::exception& e) {
            std::cout << "  EXCEPTION: " << e.what() << "\n";
            break;
        } catch (...) {
            std::cout << "  EXCEPTION: unknown (likely SIGSEGV)\n";
            break;
        }

        // Move to next point
        pi = Point(pi.x() + 10, pi.y() + 10);
    }

    return 0;
}

