        std::vector<Point> Gi = get_conv_from_grid(pi);
        Polygon Gi_poly(Gi.begin(), Gi.end());

        for (int i = 0; i < (int)P.size(); i++) {
            if (dead[i]) continue;

            int step_ref = step, i_ref = i, cur_ref = cur;
            std::vector<Point> F = find_F(p0, S[i], step_ref, i_ref, cur_ref, (step < 3 && i < 3));

            if (is_bbox(F)) {
                continue;
            }

            Polygon F_poly(F.begin(), F.end());

            if (!F_poly.is_simple() || !Gi_poly.is_simple()) {
                std::cout << "    S[" << i << "]: skipping intersection (not simple)\n";
                dead[i] = 1;
                dead_cnt++;
                continue;
            }

            std::vector<PolygonHoles> result;
            try {
                CGAL::intersection(F_poly, Gi_poly, std::back_inserter(result));

                if (result.size() == 0) {
                    dead[i] = 1;
                    dead_cnt++;
                    if (step < 5 && i < 3) std::cout << "    S[" << i << "]: dead (empty intersection)\n";
                } else if (result.size() > 1) {
                    std::cerr << "\n*** ASSERTION FAILED: new_S[i].size()=" << result.size() << " != 1 ***\n";
