                } else {
                    S[i].clear();
                    for (auto it = result[0].outer_boundary().vertices_begin();
                         it != result[0].outer_boundary().vertices_end(); ++it) {
                        S[i].push_back(*it);
                    }
                    if (step < 3 && i < 3) std::cout << "    S[" << i << "]: updated, size=" << S[i].size() << "\n";
                }
            } catch (const std::exception& e) {
                std::cout << "    S[" << i << "]: EXCEPTION: " << e.what() << "\n";
                dead[i] = 1;
                dead_cnt++;
            } catch (...) {
                std::cout << "    S[" << i << "]: EXCEPTION: unknown (likely SIGSEGV)\n";
                dead[i] = 1;
                dead_cnt++;
            }
        }

        if (dead_cnt == (int)P.size()) {
            std::cout << "\nAll dead at step " << step << ", cur=" << cur << "\n";
            break;
        }

        cur++;
        step++;
        if (step >= 100) {
            std::cout << "Stopped at step 100\n";
