std::vector<Point> find_F(const Point& p, const std::vector<Point>& S) {
    if (S.size() == 1) {
        std::cerr << "[find_F] DEBUG: S.size() == 1, p=(" << p.x() << "," << p.y() << ")\n";
        return current_bbox();
    }
    if (point_in_convex(p, S)) {
        std::cerr << "[find_F] DEBUG: point_in_convex(p, S) == true, p=(" << p.x() << "," << p.y() << "), S has " << S.size() << " vertices\n";
        return current_bbox();
    }
    std::vector<int> tangent = find_tangent_idx(p, S);

    // Handle degenerate case: no tangents found (can happen with floating-point)
    if (tangent.size() != 2) {
        std::cerr << "[find_F] DEBUG: tangent.size()=" << tangent.size() << " != 2, p=(" << p.x() << "," << p.y() << "), S has " << S.size() << " vertices\n";
        std::cerr << "[find_F]   Tangent candidates: ";
        for (int idx : tangent) {
            std::cerr << idx << " ";
        }
        std::cerr << "\n";
        std::cerr << "[find_F]   S vertices: ";
        for (size_t i = 0; i < S.size(); i++) {
            std::cerr << "(" << S[i].x() << "," << S[i].y() << ") ";
        }
        std::cerr << "\n";
        return current_bbox();
    }

    std::optional<Point> hit1 = intersect_ray_with_rect(p, S[tangent[0]]);
    std::optional<Point> hit2 = intersect_ray_with_rect(p, S[tangent[1]]);
    if (!hit1 || !hit2) {
        std::cerr << "[find_F] DEBUG: no hit, p=(" << p.x() << "," << p.y() << "), S has " << S.size() << " vertices\n";
        std::cerr << "[find_F]   tangent[0]=" << tangent[0] << " -> (" << S[tangent[0]].x() << "," << S[tangent[0]].y() << "), hit1=" << (hit1 ? "ok" : "null") << "\n";
        std::cerr << "[find_F]   tangent[1]=" << tangent[1] << " -> (" << S[tangent[1]].x() << "," << S[tangent[1]].y() << "), hit2=" << (hit2 ? "ok" : "null") << "\n";
        return current_bbox();
    }
    std::optional<Bbox_edge> e1 = which_edge(hit1.value());
    std::optional<Bbox_edge> e2 = which_edge(hit2.value());
    if (!e1 || !e2) {
        std::cerr << "[find_F] DEBUG: could not determine edge, p=(" << p.x() << "," << p.y() << ")\n";
        std::cerr << "[find_F]   hit1=(" << hit1.value().x() << "," << hit1.value().y() << "), e1=" << (e1 ? "ok" : "null") << "\n";
        std::cerr << "[find_F]   hit2=(" << hit2.value().x() << "," << hit2.value().y() << "), e2=" << (e2 ? "ok" : "null") << "\n";
        return current_bbox();
    }

    int n = int(S.size());
    if (tangent[1] - tangent[0] - 1 < 1 && tangent[0] + n - tangent[1] - 1 < 1) {
        std::cerr << "[find_F] DEBUG: polygon too small, p=(" << p.x() << "," << p.y() << "), S has " << S.size() << " vertices\n";
        std::cerr << "[find_F]   tangent[0]=" << tangent[0] << ", tangent[1]=" << tangent[1] << ", n=" << n << "\n";
        std::cerr << "[find_F]   tangent[1]-tangent[0]-1=" << (tangent[1] - tangent[0] - 1) << ", tangent[0]+n-tangent[1]-1=" << (tangent[0] + n - tangent[1] - 1) << "\n";
        return current_bbox();
    }
    std::vector<Point> F;
    if (CGAL::right_turn(p, S[tangent[0]], S[tangent[1]]))  {
        std::copy(S.begin() + tangent[0], S.begin() + tangent[1] + 1,
                  std::back_inserter(F));
        F.push_back(hit2.value());
        append_rect_pts(F, e2.value(), e1.value(), true);
        F.push_back(hit1.value());
    } else {
        std::copy(S.begin() + tangent[1], S.end(),
                  std::back_inserter(F));
        std::copy(S.begin(), S.begin() + tangent[0] + 1,
                  std::back_inserter(F));
        F.push_back(hit1.value());
        append_rect_pts(F, e1.value(), e2.value(), true);
        F.push_back(hit2.value());
    }

    // Verify F forms a valid simple polygon before returning
    Polygon test_F(F.begin(), F.end());
    assert(test_F.is_simple() && "find_F: constructed polygon F is not simple!");
    assert((test_F.is_counterclockwise_oriented() || test_F.is_clockwise_oriented())
           && "find_F: polygon F has no orientation!");

    return F;
}

